from rdkit import Chem
from rdkit.Chem.rdCIPLabeler import AssignCIPLabels

smi = "CC(C)CNC(=O)/C=C/" + "".join([f"[C@H]{i}C[C@H]{i}" for i in range(1,6)]) + "/C=C/[C@H]6C[C@H]6C"
m = Chem.MolFromSmiles(smi)
AssignCIPLabels(m)
for a in m.GetAtoms():
    if a.HasProp('_CIPCode'):
        print(a.GetIdx(), a.GetSymbol(), a.GetProp('_CIPCode'))
for b in m.GetBonds():
    if b.GetBondType()==Chem.BondType.DOUBLE:
        print("dbl", b.GetBeginAtomIdx(), b.GetEndAtomIdx(), b.GetStereo(), [ (x.GetIdx(),x.GetSymbol()) for x in (b.GetBeginAtom().GetNeighbors())], [ (x.GetIdx(),x.GetSymbol()) for x in (b.GetEndAtom().GetNeighbors())])
EOF
